-- A dedicated two-image tool: the source outfit plus an immutable application-owned display reference.
ALTER TABLE media_function_setting DROP CONSTRAINT media_function_setting_operation_check;
ALTER TABLE media_function_setting ADD CONSTRAINT media_function_setting_operation_check
    CHECK (operation IN ('IMAGE_SMART_EDIT', 'IMAGE_COSTUME_EXTRACT', 'IMAGE_RELIGHT', 'IMAGE_OUTPAINT', 'IMAGE_THREE_VIEW', 'IMAGE_LAYER_SPLIT', 'IMAGE_EXPRESSION_EDIT', 'IMAGE_REMOVE_BACKGROUND', 'IMAGE_OBJECT_REMOVE', 'IMAGE_VIEW_ANGLE', 'IMAGE_DEPTH_MAP', 'IMAGE_UPSCALE', 'IMAGE_RESIZE', 'IMAGE_CROP', 'IMAGE_ROTATE', 'IMAGE_FLIP_HORIZONTAL', 'IMAGE_FLIP_VERTICAL', 'VIDEO_DEPTH_MAP', 'VIDEO_EXTRACT_AUDIO', 'VIDEO_UPSCALE'));
COMMENT ON CONSTRAINT media_function_setting_operation_check ON media_function_setting IS 'Allow only compiled image and video processing functions';
INSERT INTO media_function_setting (operation, capability_id) VALUES ('IMAGE_COSTUME_EXTRACT', NULL);

INSERT INTO prompt_definition (id, key, kind, name, description, content, built_in)
VALUES ('00000000-0000-4000-8000-000000000409', 'image.costume-extract', 'FUNCTION', '服装提取',
    '提取原图穿搭，以固定参考图约束背景、光照和摆放，不复制参考图中的服装。',
    'Extract the complete visible outfit worn by the main person in Image 1. Image 1 is the ONLY source of garment identity: preserve its exact clothing designs, layers, colors, patterns, materials, fastenings and proportions, including shoes, socks, bags, hats and worn accessories when visible. Image 2 is ONLY a presentation-style example: use its neutral light-gray seamless studio background, soft diffuse lighting, centered full-length front-facing layout, generous margins and subtle ground shadows. NEVER copy, borrow, replace or add any garment, color, pattern, bag or shoe from Image 2. Remove all people, skin, body parts, faces, hair, visible mannequins, hangers, scenery, text and unrelated props. Keep natural three-dimensional worn volume on a completely invisible body, with hollow neck and sleeve openings; arrange garments, shoes and accessories coherently at their normal worn positions, not as a pile or flat lay. Preserve only what belongs to the selected source outfit, conservatively complete small occluded areas needed for a continuous garment, and do not invent additional pieces. Return one clean catalog image, full outfit entirely in frame, portrait 2:3, no labels or border.', true);
